import math

def interp(points, x):
    p=sorted(points)
    for i in range(len(p)-1):
        a,b=p[i],p[i+1]
        if a[0]<=x<=b[0] and b[0]-a[0]>0.01:
            return a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0])
    return None

def control(obs):
    m=obs['local_map']
    centers=[]
    for x in (2.0,4.0,6.0,8.0):
        l=interp(m['left_rail'],x); r=interp(m['right_rail'],x)
        if l is not None and r is not None: centers.append((x,(l+r)/2))
    target=0.0
    if centers:
        x,y=centers[min(2,len(centers)-1)]
        target=max(-22,min(22,math.degrees(math.atan2(y,x))*1.3))
    hitch=obs['hitch_deg']
    steer=max(-40,min(40,2.0*(hitch-target)))
    return steer,-0.8

